// R4g-turnbox TB-1 (transcript-turn-box, tasks-06a): the 2.42304.0 Code session turn box generated by
// scripts/extract-turn-box.mjs — cccc2cf0a CT / DT / ET / wT / TT / xT / ST / nv / rv / iv / hT and c1ebb1aa4 N_'s pure
// derivation Rt / Et with the dismissed next-row memory — over src/source-turn-box-adapters.jsx. SSR for the markup, the
// pure functions called directly. No browser, no DOM, no network; nothing here reads a real session.
import test, { before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { createServer } from 'vite';
import react from '@vitejs/plugin-react';
import { extractTurnBox } from '../scripts/extract-turn-box.mjs';

const app = path.resolve(import.meta.dirname, '..');
const generated = path.join(app, 'src/generated/turn-box');
const reference = path.resolve(app, '../reference/installed-2.42304.0-20261017/ion-dist/assets/v1');
const official = name => fs.readFileSync(path.join(reference, name), 'utf8');
const count = (text, needle) => text.split(needle).length - 1;
let server, B, A, T, E;
before(async () => {
  // ws: false — no WebSocket server, so the test listens on no port.
  server = await createServer({ configFile: false, root: app, plugins: [react()],
    server: { middlewareMode: true, hmr: false, ws: false, watch: null }, appType: 'custom', logLevel: 'error' });
  B = await server.ssrLoadModule('/src/generated/turn-box/turn-box.mjs');
  A = await server.ssrLoadModule('/src/source-turn-box-adapters.jsx');
  T = await server.ssrLoadModule('/src/generated/turn-box/turn-tail.mjs');
  E = await server.ssrLoadModule('/src/generated/turn-box/epitaxy-session.mjs');
});
after(async () => { await server?.close(); });

const ref = { id: 'local_s1', type: 'local' };
const plan = [
  { id: 'plan-0', content: 'Read the code', status: 'completed' },
  { id: 'plan-1', content: 'Fix the bug', status: 'in_progress' },
  { id: 'plan-2', content: 'Run the tests', status: 'pending' },
];
const tail = fields => ({ ...T.EMPTY_TURN_TAIL, ...fields });
const render = (host, props) => renderToStaticMarkup(React.createElement(A.TurnBoxHost.Provider, { value: host }, React.createElement(B.TurnBox, props)));

test('TB-1 generator: the emitted originals are current, closed and pinned to the installed sources', async () => {
  const manifest = await extractTurnBox({ check: true });
  assert.equal(manifest.referenceVersion, '2.42304.0');
  assert.equal(manifest.adapterModule, 'src/source-turn-box-adapters.jsx');
  const targets = manifest.modules.map(m => m.target);
  for (const name of ['turn-box.mjs', 'turn-tail.mjs', 'epitaxy-session.mjs', 'todo-list.mjs', 'spinner.mjs', 'visible-window.mjs'])
    assert.ok(targets.includes(name), name);
  // Generated modules come before the modules importing them.
  assert.ok(targets.indexOf('turn-tail.mjs') < targets.indexOf('turn-box.mjs'));
  assert.ok(targets.indexOf('epitaxy-session.mjs') < targets.indexOf('turn-tail.mjs'));
  const box = manifest.modules.find(m => m.target === 'turn-box.mjs');
  assert.equal(box.source, 'cccc2cf0a-B0D--VZp.js');
  for (const root of ['CT', 'DT', 'ET', 'wT', 'TT', 'xT', 'ST', 'nv', 'rv', 'iv', 'hT']) assert.ok(box.bindings.some(b => b.name === root), root);
  const tailModule = manifest.modules.find(m => m.target === 'turn-tail.mjs');
  assert.equal(tailModule.source, 'c1ebb1aa4-c89yWBMH.js');
  for (const root of ['Rt', 'Et', 'Bt', 'Ke', 'G', 'Ge']) assert.ok(tailModule.bindings.some(b => b.name === root), root);
  // N_ itself (Wt, over the desktop's message store) is the host's adapter, not generated.
  assert.ok(!tailModule.bindings.some(b => b.name === 'Wt'));
  assert.deepEqual(box.imports.find(i => i.local === 'N_'), { local: 'N_', from: '../../source-turn-box-adapters.jsx', name: 'useTurnTail',
    via: 'c1ebb1aa4-c89yWBMH.js:n', kind: 'adapter', original: 'Wt' });
  // D1/D24: view-tabs only by semantic name.
  for (const module of manifest.modules) for (const entry of module.imports) {
    if (entry.kind === 'view-tabs') assert.match(entry.name, /^(Cds|cds)/, `${module.target} ${entry.local}`);
    if (entry.kind === 'generated') assert.ok(entry.from.startsWith('./'), `${module.target} ${entry.from}`);
    if (entry.kind === 'adapter') assert.equal(entry.from, '../../source-turn-box-adapters.jsx');
  }
  for (const name of fs.readdirSync(generated).filter(n => n.endsWith('.mjs'))) {
    const text = fs.readFileSync(path.join(generated, name), 'utf8');
    for (const [, from] of text.matchAll(/from "([^"]+)"/g))
      assert.ok(from.startsWith('./') || from.startsWith('../view-tabs/') || from === '../../source-turn-box-adapters.jsx' || from === 'react' || from === 'react/jsx-runtime',
        `${name} imports ${from}`);
  }
  // The mount the host follows (cc43287c9 Mte / O5, cf74bc599's slot, the presets gate, the main-process turnBox gate).
  const raw = manifest.callSites.filter(s => s.raw).flatMap(s => s.features);
  assert.ok(raw.includes('{slotEl:oo,placeable:so,probeRef:co}=O5(Zn,ao),lo=Na&&da&&!tn&&!on,uo=lo&&so,fo=lo&&tr!==null&&Yr'));
  assert.ok(raw.includes('function Iq(e){let t=Pq(e),n=yf();return t||n&&e!=null}'));
  assert.ok(raw.includes('function ht(){return t.LZ("2371478310")}'));
});

test('TB-1 root features: the installed chunks carry each pinned string once, the generated module keeps it', () => {
  const box = official('cccc2cf0a-B0D--VZp.js');
  for (const needle of ['CT=E(function({sessionRef:e', '[&:has(+[data-turn-next]_p:not([hidden]_p))]:hidden', 'Plan from before your last message',
    'function rv({plan:e,planBeforeWrapUp:t', 'create_pr:!0,archive:W,new_session:!0', 'epitaxy-root motion-safe:animate-fade-in', 'CT as g'])
    assert.equal(count(box, needle), 1, needle);
  assert.equal(count(official('c1ebb1aa4-c89yWBMH.js'), 'kt=new Set(["TodoWrite","TaskCreate","TaskUpdate"])'), 1);
  assert.equal(count(official('cf74bc599-D9NZWRyl.js'), 'Qn as EpitaxyTurnBox'), 1);
  const text = fs.readFileSync(path.join(generated, 'turn-box.mjs'), 'utf8');
  assert.equal(count(text, '[&:has(+[data-turn-next]_p:not([hidden]_p))]:hidden'), 1);
  assert.equal(count(text, 'var CT = E(function ({'), 1);
  assert.equal(count(text, '"data-turn-next": "",'), 1);
});

test('TB-1 rv: the four plan snapshots of the turn tail', () => {
  const { planSnapshot } = B;
  // No plan, or an empty one: no card.
  assert.equal(planSnapshot(tail({}), true, false), null);
  assert.equal(planSnapshot(tail({ plan: [] }), true, false), null);
  // Responding and the plan was touched this turn: the live plan.
  assert.deepEqual(planSnapshot(tail({ plan, planTouchedThisTurn: true }), true, false), { todos: plan, stale: false, working: true });
  // Responding, the plan is from before the last message: stale "prompt" ("Plan from before your last message").
  assert.deepEqual(planSnapshot(tail({ plan }), true, false), { todos: plan, stale: 'prompt', working: true });
  // A compaction since the plan was written.
  assert.deepEqual(planSnapshot(tail({ plan, planTouchedThisTurn: true, compactedSincePlan: true }), true, false), { todos: plan, stale: 'compaction', working: true });
  // An untouched plan whose steps are all done is not shown while responding.
  const done = plan.map(step => ({ ...step, status: 'completed' }));
  assert.equal(planSnapshot(tail({ plan: done }), true, false), null);
  // After the turn: shown, not working, only while agents run (or side sessions are parked) and the turn touched it.
  assert.equal(planSnapshot(tail({ plan, planTouchedThisTurn: true, planTurnEnded: true }), true, false), null);
  assert.deepEqual(planSnapshot(tail({ plan, planTouchedThisTurn: true, agentsRunning: 2 }), false, false), { todos: plan, stale: false, working: false });
  assert.deepEqual(planSnapshot(tail({ plan, planTouchedThisTurn: true }), false, true), { todos: plan, stale: false, working: false });
  assert.equal(planSnapshot(tail({ plan, agentsRunning: 1 }), false, false), null);
  // planBeforeWrapUp wins only while side sessions are parked; it stays null in this host (wrap_up off, D29).
  const before = [{ id: 'plan-0', content: 'Earlier', status: 'pending' }];
  assert.deepEqual(planSnapshot(tail({ plan, planBeforeWrapUp: before, planTouchedThisTurn: true }), true, true).todos, before);
});

test('TB-1 Rt: the turn tail over SDK messages, and the task-todo branch the host plan maps onto (TB-2)', () => {
  const { deriveTurnTail, EMPTY_TURN_TAIL, turnTailEqual, TASK_TOOL_NAMES } = T;
  assert.deepEqual(Object.keys(EMPTY_TURN_TAIL), ['wrapUp', 'wrapUpCallId', 'wrapUpReceipt', 'plan', 'planBeforeWrapUp', 'planTouchedThisTurn', 'planTurnEnded',
    'compactedSincePlan', 'turnSettled', 'agentsRunning', 'workedWithoutWrapUp', 'proposedTaskIds']);
  assert.deepEqual([...TASK_TOOL_NAMES], ['TodoWrite', 'TaskCreate', 'TaskUpdate']);
  const prompt = { type: 'user', uuid: 'p1', message: { role: 'user', content: 'Fix it' } };
  const todoWrite = { type: 'assistant', uuid: 'a1', message: { role: 'assistant', content: [{ type: 'tool_use', id: 'tu1', name: 'TodoWrite', input: { todos: [] } }] } };
  const result = { type: 'user', uuid: 'r1', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'tu1', content: 'ok' }] } };
  const messages = [prompt, todoWrite, result];
  // Without task todos the plan is read from mcp__ccd_turn__update_plan calls (the turn box tool set, off here): none.
  assert.equal(deriveTurnTail(messages, 'p1', undefined).plan, null);
  // With task todos (the desktop's TodoWrite / TaskCreate list) the plan is that list; wrap-up fields stay null.
  const derived = deriveTurnTail(messages, 'p1', plan);
  assert.deepEqual(derived.plan, plan);
  assert.equal(derived.planTouchedThisTurn, true);
  assert.equal(derived.wrapUp, null);
  assert.equal(derived.planBeforeWrapUp, null);
  assert.equal(derived.wrapUpCallId, null);
  assert.equal(turnTailEqual(derived, deriveTurnTail(messages, 'p1', plan.map(step => ({ ...step })))), true);
  assert.equal(turnTailEqual(derived, EMPTY_TURN_TAIL), false);
});

test('TB-1 gates: presets on (D10) opens the turn box for any session; turn-plan: the per-session turnBox flag is on for a local session (GrowthBook 2371478310, the ccd_turn tools)', () => {
  assert.equal(E.canHostTurnBox(ref), true);
  assert.equal(E.canHostTurnBox({ id: 'remote_1', type: 'remote' }), true);
  assert.equal(E.canHostTurnBox(null), false);
  assert.equal(E.canHostTurnBox(undefined), false);
  assert.equal(E.sessionHasTurnBox(ref), ref.type === 'local');
  assert.equal(E.sessionHasTurnBox({ id: 'remote_1', type: 'remote' }), false);
});

test('TB-1 CT: the card renders DT while a touched plan is working; the next row sits in [data-turn-next]', () => {
  const host = { turnTail: () => tail({ plan, planTouchedThisTurn: true }) };
  const html = render(host, { sessionRef: ref, isResponding: true, latestPromptId: 'p1',
    children: React.createElement(B.NextActionsRow, { sessionRef: ref, composerRef: { current: null }, latestPromptId: 'p1' }) });
  assert.match(html, /^<div class="mt-\[var\(--chat-turn-gap,15px\)\] epitaxy-root motion-safe:animate-fade-in text-body text-primary break-words overflow-clip rounded-card shadow-\[inset_0_0_0_1px_var\(--cds-ring-color\)\]/);
  assert.equal(count(html, 'class="flex flex-col gap-1 p-4 [&amp;:has(+[data-turn-next]_button:not([hidden]_button):not([data-turn-dismiss]_button))]:hidden [&amp;:has(+[data-turn-next]_p:not([hidden]_p))]:hidden"'), 1);
  for (const step of plan) assert.equal(count(html, step.content), 1, step.content);
  assert.equal(count(html, 'data-cds="Spinner"'), 1, 'the in-progress step spins');
  assert.match(html, /<div data-turn-next="" hidden="" class="p-4 /, 'the next row is hidden while the turn runs with a plan');
  assert.doesNotMatch(html, /Plan from before your last message/);
  // The untouched plan of an earlier prompt.
  const stale = render({ turnTail: () => tail({ plan }) }, { sessionRef: ref, isResponding: true, latestPromptId: 'p2' });
  assert.equal(count(stale, 'Plan from before your last message'), 1);
  assert.equal(count(stale, 'data-cds="Spinner"'), 0, 'a stale plan does not spin');
  // The step window: 12 around the open step, with "# earlier steps" / "# more to go".
  const long = Array.from({ length: 20 }, (_, i) => ({ id: `plan-${i}`, content: `Step ${i}`, status: i < 15 ? 'completed' : i === 15 ? 'in_progress' : 'pending' }));
  const windowed = render({ turnTail: () => tail({ plan: long, planTouchedThisTurn: true }) }, { sessionRef: ref, isResponding: true, latestPromptId: 'p1' });
  assert.equal(count(windowed, '<li '), B.TODO_WINDOW);
  assert.match(windowed, /\d+ earlier steps?/);
});

test('TB-1 CT: no tail, no card body; a waiting request parks the spinner; nextStepOnly drops DT', () => {
  const empty = render(null, { sessionRef: ref, isResponding: true, latestPromptId: 'p1' });
  assert.doesNotMatch(empty, /<li /);
  assert.match(empty, /data-turn-next=""/);
  const host = { turnTail: () => tail({ plan, planTouchedThisTurn: true }), awaitsRequest: id => id === ref.id };
  assert.equal(count(render(host, { sessionRef: ref, isResponding: true, latestPromptId: 'p1' }), 'data-cds="Spinner"'), 0);
  assert.doesNotMatch(render(host, { sessionRef: ref, isResponding: true, latestPromptId: 'p1', nextStepOnly: true }), /<li /);
});

test('TB-1 hT: with no wrap-up and no rule source the next row renders nothing', () => {
  const html = renderToStaticMarkup(React.createElement(B.NextActionsRow, { sessionRef: ref, composerRef: { current: null }, latestPromptId: 'p1', turnSettled: true }));
  assert.equal(html, '');
});
